pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize creating bins with very low residual space
    if post_residual < 15.0 {
        score += (15.0 - post_residual) * 10.0;
    }

    // Reward using bins that are already nearly full
    if bin_residual <= 30.0 {
        score -= bin_residual as f64 / 7.5;
    }

    // Penalize using too many open bins
    score += (open_bins_count - 1) as f64 * 2.5;

    // Reward fitting items into existing bins
    if fitting_bins_count > 2 {
        score -= 0.2 * fitting_bins_count as f64;
    }

    // Penalize high mean residual across open bins
    score += (mean_residual - 70.0) / 70.0 * 15.0;

    // Reward items that fit into both the current and next bin
    if post_residual >= next_item_size {
        score -= 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Favor using bins that can fit the item
    if fitting_bins_count > 0 {
        score += 1.0 / (fitting_bins_count as f64);
    }

    // Penalize creating small residual spaces
    if post_residual < 20 {
        score -= (20 - post_residual) as f64 * 0.5;
    }

    // Favor using bins with higher remaining capacity
    if bin_capacity - post_residual > mean_residual {
        score += ((bin_capacity - post_residual) - mean_residual) / 10.0;
    }

    // Penalize creating new bins
    if fitting_bins_count == 0 {
        score -= 0.5;
    }

    // Favor using bins with lower residual spaces on average
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Favor items that are closer to the end of the stream
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.5 {
        score *= progress * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize bins with very little space left
    if post_residual < 10 {
        score += 5.0;
    }

    // Reward bins that can fit the next item without opening a new bin
    if fitting_bins_count > 0 {
        score -= 2.0;
    }

    // Penalize bins with low mean residual across open bins
    if mean_residual < 10.0 {
        score += 3.0;
    }

    // Reward bins with high capacity utilization (close to full)
    if bin_capacity - post_residual < 20 {
        score -= 1.5;
    }

    // Penalize bins that have a next item larger than their remaining space
    if next_item_size > post_residual {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let stream_progress = step_index as f64 / total_items as f64;
    let bin_efficiency = (bin_capacity as f64 - bin_residual as f64).powf(0.8);
    let post_adjustment = if post_residual < mean_residual { 1.7 } else { 0.3 };
    let score = post_residual as f64 * post_adjustment * (1.0 - stream_progress).powi(2) + bin_efficiency * 0.9 - next_item_size as f64 * 0.3;
    score
}

